import{_ as r,l as n,o as e,c as l,v as t,p as s,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"位图索引","description":"","frontmatter":{"title":"位图索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bitmap-index.md","filePath":"cs/bitmap-index.md","lastUpdated":1789023840000}'),h={name:"cs/bitmap-index.md"};function D(m,a,E,_,A,B){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="位图索引" tabindex="-1">位图索引 <a class="header-anchor" href="#位图索引" aria-label="Permalink to &quot;位图索引&quot;">​</a></h1><div class="epigraph"><p>每个值一条位向量，行号对位；AND/OR 做谓词交并，扫描变成位运算，适合低 NDV 的分析列。</p><footer>—— 据 O&#39;Neil 位图索引；Wu, O&#39;Neil 等压缩位图；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/zone-maps">上一课</a>用粗摘要跳过区。本课不维护 min/max。缺口是低基数列（国家、状态、日期天）上的精确过滤：B+ 叶子对每个键挂 RID 列表，列表很长时交谓词要排 RID。位图：值 \\(v\\) 对应长度为 \\(N\\) 的位向量，第 \\(i\\) 位表示行 \\(i\\) 是否取 \\(v\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NDV 高（主键）则位图张数爆炸、几乎全 0，不如 B+。NDV 低则向量少，压缩后（Roaring、BBC、WAH）更小。多谓词：<code>color=red AND size=L</code> 是两向量 AND，再从置位取行。缺口是<strong>只读或追加型分析表</strong>上维护便宜；OLTP 频繁改行则要改多张向量，写放大差。</p><p>NULL 单独一向量。与连接：星型后课可用位图做维表过滤再探事实表。本课单表过滤。</p><p><span class="marginnote">Patrick O&#39;Neil 位图索引工作。压缩位图让稀疏也可接受。本课不把位图当全文倒排——倒排下一课，键是词项不是低 NDV 维值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建：全表扫，为每个值置位。查询：取向量、位运算、解码 RID。与 zone：先 zone 跳区，区内再位图或再扫。向量化：把置位转成选择向量。</p><p>维护：原地更新翻比特；插入追加位。删除可翻或延迟与 vacuum 一起重建。MVCC：位图必须对应某一行版本集合，否则看见幽灵——常对只读副本或物化快照建位图。</p>',10)),(e(),s(c,null,{default:i(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20V1%5B%22%E5%80%BC%20A%20%E7%9A%84%E4%BD%8D%E5%9B%BE%22%5D%20--%3E%20AND%5B%22%E6%8C%89%E4%BD%8D%20AND%20%2F%20OR%22%5D%0A%20%20V2%5B%22%E5%80%BC%20B%20%E7%9A%84%E4%BD%8D%E5%9B%BE%22%5D%20--%3E%20AND%0A%20%20AND%20--%3E%20RID%5B%22%E7%BD%AE%E4%BD%8D%E8%A1%8C%E5%8F%B7%22%5D%0A%20%20RID%20--%3E%20FETCH%5B%22%E5%9B%9E%E8%A1%A8%E6%88%96%E8%A6%86%E7%9B%96%E5%88%97%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优化器：位图扫描代价 ≈ 向量体积 + 置位密度 × 回表。选择率估错会低估回表随机 I/O。覆盖：若查询列都在别处，可能只定位行号。</p><p>并行：按行号分段切向量。exchange 传位图段比传行宽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲倒排词表。也不把位图连接索引（join index）写完，只点名星型可用。学习索引不替代位图的位运算。</p><p>后课默认：低 NDV 分析列可位图；高更新表慎用。倒排与全文：词项→位置列表，是搜索引擎与 <code>LIKE</code>/<code>@@</code> 的结构。</p><p>位图是行集合的特征函数，不是哈希索引。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>低 NDV 列用位向量做谓词交并，CPU 友好。</li><li>高更新与高 NDV 不适合；版本要与 MVCC 对齐。</li><li>倒排与全文下一课：词项列表而非维值。</li><li>出处：O&#39;Neil；压缩位图文献；Ramakrishnan and Gehrke。</li></ul>',9))])}const f=r(h,[["render",D]]);export{u as __pageData,f as default};
